async function listOrders(filters, d1Database) {
  const prisma2 = getPrismaClient(d1Database);
  const page = Math.max(1, filters.page || 1);
  const limit = Math.min(100, Math.max(1, filters.limit || 25));
  const where = {};
  if (filters.status && filters.status !== "ALL") {
    if (filters.status === "PENDING") {
      where.status = { in: ["PENDING", "Ch\u1EDD x\xE1c nh\u1EADn", "\u0110ang x\u1EED l\xFD", "\u0110ang v\u1EADn chuy\u1EC3n"] };
    } else if (filters.status === "COMPLETED") {
      where.status = { in: ["COMPLETED", "\u0110\xE3 ho\xE0n th\xE0nh"] };
    } else {
      where.status = filters.status;
    }
  }
  if (filters.search?.trim()) {
    const q3 = filters.search.trim();
    where.OR = [
      { orderNumber: { contains: q3 } },
      { customerName: { contains: q3 } },
      { customerPhone: { contains: q3 } },
      { customerEmail: { contains: q3 } }
    ];
  }
  const [total, orders] = await Promise.all([
    prisma2.order.count({ where }),
    prisma2.order.findMany({
      where,
      include: {
        items: {
          select: {
            id: true,
            productId: true,
            productName: true,
            sku: true,
            quantity: true,
            price: true,
            lineTotal: true
          }
        }
      },
      orderBy: { createdAt: "desc" },
      skip: (page - 1) * limit,
      take: limit
    })
  ]);
  return {
    orders,
    pagination: {
      page,
      limit,
      total,
      totalPages: Math.ceil(total / limit)
    }
  };
}
async function updateOrderStatus(orderId, newStatus, d1Database) {
  const prisma2 = getPrismaClient(d1Database);
  const existing = await prisma2.order.findUnique({
    where: { id: orderId },
    select: { id: true, status: true }
  });
  if (!existing) {
    throw new Error("ORDER_NOT_FOUND");
  }
  const isCompleted = newStatus === "COMPLETED";
  return prisma2.order.update({
    where: { id: orderId },
    data: {
      status: newStatus,
      completedAt: isCompleted ? /* @__PURE__ */ new Date() : null,
      updatedAt: /* @__PURE__ */ new Date()
    },
    include: { items: true }
  });
}

